/* LeaveHourlyResettleMapper.selectRemnantCoveredReqIds */
SELECT DISTINCT C.REQ_ID
  FROM TB_LEAVE_REMNANT_COVER C
 WHERE C.CMPNY_CD = #{cmpnyCd}
   AND C.USER_CD  = #{userCd}
   AND C.WORK_YMD = #{workYmd}
   AND C.DEL_YN   = 'N'
   AND C.REQ_ID IS NOT NULL

mapper.update:
/* LeaveHourlyResettleMapper.updateLeaveUseDays */
UPDATE TB_USER_LEAVE_USE
   SET LEAVE_DAYS  = #{leaveDays}
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND LEAVE_ID     = #{leaveId}
   AND LEAVE_STATUS = 'CONFIRMED'
   AND DEL_YN       = 'N'

/* LeaveHourlyResettleMapper.recomputeGrantUsedDays */
UPDATE TB_USER_LEAVE_GRANT G
   SET G.USED_DAYS = IFNULL((
           SELECT SUM(U.LEAVE_DAYS)
             FROM TB_USER_LEAVE_USE U
            WHERE U.CMPNY_CD     = G.CMPNY_CD
              AND U.GRANT_ID     = G.GRANT_ID
              AND U.LEAVE_STATUS = 'CONFIRMED'
              AND U.DEL_YN       = 'N'
       ), 0)
     , G.UPDATE_NO   = #{updateNo}
     , G.UPDATE_DATE = NOW()
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.GRANT_ID = #{grantId}
